DECLARE
  v_age PLS_INTEGER := 20;
  c_limit CONSTANT PLS_INTEGER := 100;
BEGIN
  v_age := 21;
  DBMS_OUTPUT.PUT_LINE(v_age);
END;

DECLARE
  v_amount NUMBER(12, 2) := 123.45;
  v_ok BOOLEAN := TRUE;
BEGIN
  IF v_ok THEN
    DBMS_OUTPUT.PUT_LINE(v_amount);
  END IF;
END;

DECLARE
  v_role VARCHAR2(20) := 'admin';
BEGIN
  CASE v_role
  WHEN 'admin' THEN
    DBMS_OUTPUT.PUT_LINE('管理者');
  ELSE
    DBMS_OUTPUT.PUT_LINE('その他');
  END CASE;
END;

DECLARE
  v_name VARCHAR2(100);
BEGIN
  SELECT name INTO v_name
  FROM users
  WHERE id = 1;
  DBMS_OUTPUT.PUT_LINE(v_name);
END;

DECLARE
  v_id NUMBER;
BEGIN
  INSERT INTO users(name) VALUES('Pomo')
  RETURNING id INTO v_id;
  DBMS_OUTPUT.PUT_LINE(v_id);
END;

DECLARE
  CURSOR c_users IS SELECT name
  FROM users;
BEGIN
  FOR r IN c_users LOOP
    DBMS_OUTPUT.PUT_LINE(r.name);
  END LOOP;
END;

DECLARE
  CURSOR c IS SELECT name
  FROM users;
  v_name users.name%TYPE;
BEGIN
  OPEN c;
  LOOP
    FETCH c INTO v_name;
    EXIT WHEN c%NOTFOUND;
    DBMS_OUTPUT.PUT_LINE(v_name);
  END LOOP;
  CLOSE c;
END;

DECLARE
  TYPE names_t IS TABLE OF VARCHAR2(100) INDEX BY PLS_INTEGER;
  names names_t;
BEGIN
  names(1) := 'Pomo';
  DBMS_OUTPUT.PUT_LINE(names.COUNT);
END;

DECLARE
  TYPE ids_t IS TABLE OF users.id%TYPE;
  ids ids_t;
BEGIN
  SELECT id BULK COLLECT INTO ids
  FROM users;
  DBMS_OUTPUT.PUT_LINE(ids.COUNT);
END;

DECLARE
  TYPE ids_t IS TABLE OF NUMBER;
  ids ids_t := ids_t(1, 2, 3);
BEGIN
  FORALL i IN 1..ids.COUNT UPDATE users SET name = 'New'
  WHERE id = ids(i);
END;

